create table if not exists public.spike_live_questions (id uuid primary key default gen_random_uuid(), stream_id uuid not null references public.spike_live_streams(id) on delete cascade, user_id uuid not null, question text not null check(char_length(question) between 3 and 500), status text not null default 'pending' check(status in ('pending','answered','dismissed')), created_at timestamptz not null default now(), answered_at timestamptz);
create table if not exists public.spike_live_presence (stream_id uuid not null references public.spike_live_streams(id) on delete cascade, user_id uuid not null, role text not null default 'viewer' check(role in ('viewer','host','guest')), last_seen_at timestamptz not null default now(), primary key(stream_id,user_id));
create table if not exists public.spike_live_moderation_actions (id uuid primary key default gen_random_uuid(), stream_id uuid not null references public.spike_live_streams(id) on delete cascade, moderator_id uuid not null, target_user_id uuid, action text not null check(action in ('warn','mute','remove','block')), reason text, created_at timestamptz not null default now());
alter table public.spike_live_questions enable row level security;
alter table public.spike_live_presence enable row level security;
alter table public.spike_live_moderation_actions enable row level security;
grant select,insert,update on public.spike_live_questions to authenticated;
grant select,insert,update on public.spike_live_presence to authenticated;
grant select,insert on public.spike_live_moderation_actions to authenticated;
create index if not exists idx_live_questions_stream_status on public.spike_live_questions(stream_id,status,created_at);
create index if not exists idx_live_presence_stream_seen on public.spike_live_presence(stream_id,last_seen_at desc);
create index if not exists idx_live_mod_stream_created on public.spike_live_moderation_actions(stream_id,created_at desc);
drop policy if exists "questions select live" on public.spike_live_questions; create policy "questions select live" on public.spike_live_questions for select to authenticated using(exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.status='live'));
drop policy if exists "questions insert own" on public.spike_live_questions; create policy "questions insert own" on public.spike_live_questions for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.status='live'));
drop policy if exists "questions host update" on public.spike_live_questions; create policy "questions host update" on public.spike_live_questions for update to authenticated using(exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.host_id=(select auth.uid()))) with check(exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.host_id=(select auth.uid())));
drop policy if exists "presence select live" on public.spike_live_presence; create policy "presence select live" on public.spike_live_presence for select to authenticated using(exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.status='live'));
drop policy if exists "presence own upsert" on public.spike_live_presence; create policy "presence own upsert" on public.spike_live_presence for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.status='live'));
drop policy if exists "presence own update" on public.spike_live_presence; create policy "presence own update" on public.spike_live_presence for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
drop policy if exists "mod host insert" on public.spike_live_moderation_actions; create policy "mod host insert" on public.spike_live_moderation_actions for insert to authenticated with check(moderator_id=(select auth.uid()) and exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.host_id=(select auth.uid())));
drop policy if exists "mod host select" on public.spike_live_moderation_actions; create policy "mod host select" on public.spike_live_moderation_actions for select to authenticated using(exists(select 1 from public.spike_live_streams s where s.id=stream_id and s.host_id=(select auth.uid())));
